    "shootingTips": "작은 흔들림도 크게 보입니다. 지지대를 쓰고 필요한 세부에 초점을 맞추세요.",
    "commonMistakes": "비교 대상의 핵심: 얼굴을 아주 크게 담아 눈과 입 주변의 미세한 표정을 강조합니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n면접을 기다리는 사람의 눈동자만 크게 담는다. 시선이 흔들리는 변화를 보여 긴장을 전달한다.\n\n촬영·표현의 핵심: 눈동자나 손끝처럼 아주 작은 부분을 화면 가득 보여 주는 샷입니다.\n화면에서 반드시 확인할 조건: 얼굴이나 사물의 일부만 보임. 주변 맥락은 거의 없음. 아주 작은 변화가 강조됨.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": null,
