    "commonMistakes": "비교 대상의 핵심: 옷감의 결, 손끝, 물건의 표면처럼 세부 모습을 강조하는 샷입니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n탐정의 책상 위 메모에서 약속 시각이 또렷하게 보인다. 관객이 다음 행동의 이유를 이해하도록 단서를 전달한다.\n\n촬영·표현의 핵심: 이야기를 이해하는 데 필요한 작은 물건이나 행동을 따로 보여 주는 샷입니다.\n화면에서 반드시 확인할 조건: 줄거리의 단서가 크게 보임. 읽어야 할 정보가 분명함. 주 장면과 연결되는 대상임.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
