    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 강가 난간의 인물을 뒤쪽 비스듬한 위치에서 찍는다. 뒷모습의 여운과 돌아볼 듯한 얼굴 단서를 함께 남긴다.\n\n촬영·표현의 핵심: 뒷모습을 중심으로 옆면도 일부 보이도록 비스듬한 뒤쪽에서 찍습니다.\n화면에서 반드시 확인할 조건: 등과 한쪽 옆면이 함께 보임. 일부 얼굴이 드러날 수 있음. 대상이 향하는 방향이 읽힘.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
