    "shootingTips": "삼각대와 초점·밝기를 함께 고정하고 촬영 사이 장비를 건드리지 마세요.",
    "commonMistakes": "동의어이거나 용례가 겹치는 명칭입니다. 카메라의 위치와 방향을 움직이지 않고 장면을 지켜보는 샷입니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 같은 방에서 의상을 바꾼 배우를 여러 번 찍어 끊김 없는 변신을 합성한다.\n\n촬영·표현의 핵심: 카메라를 단단히 고정해 화면 위치가 바뀌지 않도록 찍는 샷입니다.\n화면에서 반드시 확인할 조건: 구도 변화 없음. 배경 기준점 고정. 촬영 사이 위치도 동일.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 같은 방에서 의상을 바꾼 배우를 여러 번 찍어 끊김 없는 변신을 합성한다.\n\n0~2초: 배경 기준점과 초점·밝기를 고정한다\n2~6초: 장면의 행동만 진행하고 미세한 카메라 이동도 넣지 않는다\n6~8초: 처음과 같은 구도로 끝낸다\n\n구도 변화 없음. 배경 기준점 고정. 촬영 사이 위치도 동일. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
