    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n신발에서 시작해 발표를 준비한 학생 얼굴로 올려 중요한 인물을 소개한다.\n\n0~2초: 대상 아래쪽부터 본다\n2~6초: 카메라 높이는 그대로 두고 위로 틸트한다\n6~8초: 위쪽의 얼굴 또는 구조가 보이면 정지한다\n\n카메라 자리는 그대로. 렌즈가 위를 향함. 윗부분이 새로 드러남. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
