    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n작은 텐트에서 물러나 넓은 캠핑장을 보여 여행 공간을 소개한다.\n\n0~2초: 주 대상이 크게 보이는 위치에서 시작한다\n2~6초: 카메라가 뒤로 물러나며 주변 환경을 공개한다\n6~8초: 주변 관계가 드러나는 넓은 구도로 끝낸다\n\n대상과 간격이 늘어남. 공간 정보가 추가됨. 앞쪽 대상 크기 감소. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
