    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 배우의 옆뒤에서 앞쪽으로 비스듬히 다가가 얼굴의 결심을 드러낸다.\n\n0~2초: 대상의 옆뒤쪽에서 시작한다\n2~6초: 앞과 옆 방향을 섞은 대각선 경로로 부드럽게 접근한다\n6~8초: 앞쪽 비스듬한 위치에서 멈춘다\n\n앞뒤와 옆 이동이 섞임. 거리와 각도가 함께 변함. 끝에서 새 면이 드러남. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
