    "commonMistakes": "비교 대상의 핵심: 인물 앞에서 같은 방향으로 이동하며 다가오는 얼굴을 보여 줍니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 복도를 걸어오는 배우 앞에서 물러나며 얼굴과 접근을 계속 보여 준다.\n\n촬영·표현의 핵심: 다가오는 대상에게서 물러나듯 카메라가 뒤로 이동합니다.\n화면에서 반드시 확인할 조건: 다가오는 대상과 후퇴. 간격 유지 가능. 배경이 넓어짐.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 복도를 걸어오는 배우 앞에서 물러나며 얼굴과 접근을 계속 보여 준다.\n\n0~2초: 다가올 인물을 앞에서 본다\n2~6초: 인물이 다가오는 속도에 맞춰 카메라가 뒤로 물러난다\n6~8초: 인물이 멈추면 후퇴도 끝내고 간격을 유지한다\n\n다가오는 대상과 후퇴. 간격 유지 가능. 배경이 넓어짐. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
