    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n발표를 기다리는 사람에게 조금씩 가까워져 조용한 압박을 만든다.\n\n0~2초: 대상과 거리를 둔 고요한 구도로 시작한다\n2~6초: 짧은 거리를 매우 은근하게 앞으로 움직인다\n6~8초: 처음보다 조금 가까운 구도로 끝낸다\n\n매우 작은 접근. 움직임이 잘 안 느껴질 수 있음. 변화가 누적됨. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
