    "beginnerExplanation": "매우 급격한 줌으로 대상을 강하게 강조하는 움직임입니다. 예상 밖의 물건을 발견한 순간 화면이 확 커지면 놀라움이나 웃음을 줄 수 있습니다. 스냅 줌과 거의 같은 뜻으로 쓰이며 강한 인상을 강조합니다.",
