    "shootingTips": "놀람을 강조해도 모든 장면에 반복하면 힘이 약해집니다. 중요한 순간에만 쓰세요.",
    "commonMistakes": "동의어이거나 용례가 겹치는 명칭입니다. 줌을 빠르게 바꿔 대상을 갑자기 확대하거나 축소합니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n식탁의 예상 밖 음식으로 급히 줌해 코미디의 놀라움을 만든다.\n\n촬영·표현의 핵심: 매우 급격한 줌으로 대상을 강하게 강조하는 움직임입니다.\n화면에서 반드시 확인할 조건: 매우 급한 줌 변화. 강한 크기 대비. 끝 구도에서 의미 확정.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n식탁의 예상 밖 음식으로 급히 줌해 코미디의 놀라움을 만든다.\n\n0~2초: 넓은 화면에서 강조할 대상을 보여 준다\n2~6초: 한 번의 매우 급한 줌으로 대상을 크게 잡는다\n6~8초: 과장된 가까운 구도에서 멈춘다\n\n매우 급한 줌 변화. 강한 크기 대비. 끝 구도에서 의미 확정. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
