    "commonMistakes": "동의어이거나 용례가 겹치는 명칭입니다. 카메라를 빠르게 좌우로 돌려 휙 지나가는 화면을 만듭니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 소리를 듣고 복도 왼쪽으로 급히 돌아 다음 인물을 발견한다.\n\n촬영·표현의 핵심: 카메라 방향을 좌우로 매우 빠르게 돌려 화면을 스쳐 지나가게 합니다.\n화면에서 반드시 확인할 조건: 좌우 방향 급회전. 중간 화면이 흐림. 전후 대상은 알아볼 수 있음.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 소리를 듣고 복도 왼쪽으로 급히 돌아 다음 인물을 발견한다.\n\n0~2초: 첫 대상을 알아볼 수 있게 보여 준다\n2~6초: 카메라를 오른쪽으로 매우 빠르게 돌려 중간에 방향성 흐림을 만든다\n6~8초: 다음 대상을 알아볼 수 있도록 정지한다\n\n좌우 방향 급회전. 중간 화면이 흐림. 전후 대상은 알아볼 수 있음. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
