    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 배우 옆에서 높이 올라가 축제장 전체를 보여 규모를 알린다.\n\n0~2초: 인물 가까운 낮은 시점으로 시작한다\n2~6초: 카메라를 위로 들어 올려 더 넓은 공간을 드러낸다\n6~8초: 높아진 전체 구도에서 멈춘다\n\n높이가 올라감. 넓은 공간 공개. 팔 경로에 따라 위치도 변화. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
