    "commonMistakes": "동의어이거나 용례가 겹치는 명칭입니다. 장비의 팔을 내려 카메라의 시점을 낮추는 움직임입니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 높은 무대 시점에서 아래 배우에게 내려와 관심을 개인에게 모은다.\n\n촬영·표현의 핵심: 높은 시점에서 카메라를 내려 장면이나 인물 가까이 접근합니다.\n화면에서 반드시 확인할 조건: 높은 곳에서 낮아짐. 인물에 가까운 시점 도착. 주변 관계가 달라짐.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 높은 무대 시점에서 아래 배우에게 내려와 관심을 개인에게 모은다.\n\n0~2초: 장소가 넓게 보이는 높은 시점으로 시작한다\n2~6초: 카메라를 부드럽게 낮춰 인물 쪽으로 내려간다\n6~8초: 인물 행동이 읽히는 낮은 구도로 끝낸다\n\n높은 곳에서 낮아짐. 인물에 가까운 시점 도착. 주변 관계가 달라짐. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
