    "directingEffects": "부드러운 공간 연결",
    "practicalExamples": [
      "작은 공연 무대에서 낮은 악기와 연주자 얼굴을 이어 보여 준다.",
      "실내 제품 세트 위를 짧은 곡선으로 지나 전체 배치를 소개한다."
    ],
    "shootingTips": "작은 지브도 균형과 고정이 필요합니다. 전문 설치 기준을 따르세요.",
    "commonMistakes": "비교 대상의 핵심: 크레인의 긴 팔로 넓은 곡선을 그리며 장면을 훑습니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n작은 공연 무대에서 낮은 악기와 연주자 얼굴을 이어 보여 준다.\n\n촬영·표현의 핵심: 지렛대처럼 움직이는 촬영용 팔로 카메라를 부드럽게 이동합니다.\n화면에서 반드시 확인할 조건: 팔을 이용한 곡선 이동. 매끈한 높이 변화. 지지점과 균형 필요.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n작은 공연 무대에서 낮은 악기와 연주자 얼굴을 이어 보여 준다.\n\n0~2초: 지브 이동의 낮은 시작점을 보여 준다\n2~6초: 짧은 팔의 곡선 경로로 높이와 시점을 부드럽게 바꾼다\n6~8초: 장면의 중심이 보이는 끝 지점에서 멈춘다\n\n팔을 이용한 곡선 이동. 매끈한 높이 변화. 지지점과 균형 필요. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
