      "CAM-169": "비교 대상의 핵심: 카메라를 들어 올리며 위쪽 시점과 넓은 공간을 드러냅니다.",
      "CAM-175": "비교 대상의 핵심: 길이가 늘어나는 촬영용 크레인으로 복잡한 공간 이동을 만듭니다."
