    "commonMistakes": "비교 대상의 핵심: 드론에 장착한 카메라로 공중에서 찍는 샷입니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n해안 도로와 마을을 위에서 담아 여행 경로의 규모를 소개한다.\n\n촬영·표현의 핵심: 지상에서 높은 공중 시점으로 장소를 내려다보는 샷입니다.\n화면에서 반드시 확인할 조건: 높은 공중 시점. 지상의 큰 배치. 인물보다 장소가 우세.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n해안 도로와 마을을 위에서 담아 여행 경로의 규모를 소개한다.\n\n0~2초: 넓은 장소가 읽히는 높은 공중 시점으로 시작한다\n2~6초: 높이와 수평을 유지하며 공간을 천천히 이동한다\n6~8초: 전체 환경의 관계가 읽히는 시점으로 끝낸다\n\n높은 공중 시점. 지상의 큰 배치. 인물보다 장소가 우세. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
