    "commonMistakes": "비교 대상의 핵심: 촬영 중 초점을 한 대상에서 다른 대상으로 옮겨 관심을 전환합니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 카메라로 다가오는 배우의 눈을 따라 초점을 조절해 감정이 계속 읽히게 한다.\n\n촬영·표현의 핵심: 촬영 중 초점 거리를 조절해 필요한 대상을 선명하게 유지하거나 바꿉니다.\n화면에서 반드시 확인할 조건: 초점 거리의 조작. 움직이는 대상 선명도. 정해진 끝 초점.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 카메라로 다가오는 배우의 눈을 따라 초점을 조절해 감정이 계속 읽히게 한다.\n\n0~2초: 움직일 인물에 초점을 맞춘다\n2~6초: 인물의 접근에 맞춰 초점 거리를 바꾸어 눈을 선명하게 유지한다\n6~8초: 인물이 멈추면 초점도 유지한다\n\n초점 거리의 조작. 움직이는 대상 선명도. 정해진 끝 초점. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
