    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 복도를 걸어오는 배우를 보조 인력이 초점 조절하며 담아 표정을 유지한다.\n\n0~2초: 대상과 초점 조절 기준을 잡는다\n2~6초: 따라 움직이는 대상을 선명하게 유지하도록 초점을 조절한다\n6~8초: 대상 이동 끝까지 선명함을 유지한다\n\n움직임을 따라 초점 조절. 장치 또는 작업의 문맥. 대상 선명도 유지. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
