    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 밤 창밖 불빛을 흐려 인물의 시선이 멍해진 느낌을 표현한다.\n\n0~2초: 처음에는 대상을 알아볼 수 있게 둔다\n2~6초: 카메라는 고정하고 초점만 서서히 벗어나게 한다\n6~8초: 빛과 윤곽이 흐려진 상태로 끝낸다\n\n윤곽이 흐려짐. 정확한 선명 지점 없음. 빛이 덩어리로 보일 수 있음. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
