    "shootingTips": "닮은 대상의 크기와 위치가 다르면 연결이 약해집니다. 촬영 때 기준을 기록하세요.",
    "commonMistakes": "비교 대상의 핵심: 모양·움직임·의미가 닮은 두 화면을 이어 연결감을 만듭니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n중앙의 달에서 같은 크기 전등으로 바꿔 두 밤 공간을 연결한다.\n\n촬영·표현의 핵심: 형태나 색, 위치가 닮은 요소를 맞추어 두 장면을 연결합니다.\n화면에서 반드시 확인할 조건: 형태나 색 대응. 화면 속 위치 유사. 그래픽 요소의 연결.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n중앙의 달에서 같은 크기 전등으로 바꿔 두 밤 공간을 연결한다.\n\n0~2초: 화면 중앙의 둥근 물건을 보여 준다\n2~6초: 위치와 크기가 비슷한 다른 둥근 물건으로 컷한다\n6~8초: 새로운 장소가 함께 드러나게 한다\n\n형태나 색 대응. 화면 속 위치 유사. 그래픽 요소의 연결. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
