    "shootingTips": "교대가 너무 잦으면 행동을 놓칠 수 있습니다. 각 장면을 알아볼 시간을 주세요.",
    "commonMistakes": "비교 대상의 핵심: 서로 다른 장소의 행동을 번갈아 보여 주어 관계와 긴장감을 만듭니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n전화하는 두 사람을 오가며 각 공간의 반응을 전달한다.\n\n촬영·표현의 핵심: 다른 장면이나 화면을 사이사이에 끼워 넣으며 교대로 이어 갑니다.\n화면에서 반드시 확인할 조건: 장면 사이 삽입. 교대되는 대상. 연관을 알아볼 단서.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n전화하는 두 사람을 오가며 각 공간의 반응을 전달한다.\n\n0~2초: 두 인물 또는 공간을 알아볼 수 있게 한다\n2~6초: 서로의 반응과 행동을 교대로 끼워 넣는다\n6~8초: 현재 중심이 되는 행동으로 돌아온다\n\n장면 사이 삽입. 교대되는 대상. 연관을 알아볼 단서. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
