    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 조용한 방에서 시끄러운 축제로 바로 바꿔 인물의 놀람을 공유한다.\n\n촬영·표현의 핵심: 서로 분위기가 크게 다른 장면으로 갑자기 바꾸어 놀라움을 줍니다.\n화면에서 반드시 확인할 조건: 큰 분위기 차이. 갑작스러운 연결. 소리나 내용의 대비.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 조용한 방에서 시끄러운 축제로 바로 바꿔 인물의 놀람을 공유한다.\n\n0~2초: 조용한 방과 고요한 소리를 유지한다\n2~6초: 갑자기 활기찬 다른 장소로 컷하고 분위기를 크게 바꾼다\n6~8초: 새 장면을 안정적으로 유지한다\n\n큰 분위기 차이. 갑작스러운 연결. 소리나 내용의 대비. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
