    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 배우가 프레임을 가리는 순간 두 촬영분을 이어 한 번에 걷는 듯 보여 준다.\n\n0~2초: 이어지는 행동의 시작을 보여 준다\n2~6초: 움직임이나 가림 속에서 편집하되 밝기와 방향을 맞춘다\n6~8초: 한 번에 촬영한 듯 같은 행동을 이어 간다\n\n편집 경계가 안 두드러짐. 움직임·빛 연결. 연속 촬영처럼 보일 수 있음. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
