    "shootingTips": "생략한 과정이 추론되도록 의상·소품·장소의 연속성을 남기세요.",
    "commonMistakes": "비교 대상의 핵심: 비슷한 구도에서 시간 일부를 빼 인물이나 동작이 갑자기 건너뛴 듯 보이게 합니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n집을 나서는 사람 다음에 버스에서 내리는 모습을 보여 이동 시간을 생략한다.\n\n촬영·표현의 핵심: 행동의 중간 과정을 생략해 시간이 지났음을 자연스럽게 전합니다.\n화면에서 반드시 확인할 조건: 과정의 중간이 빠짐. 전후 변화가 이해됨. 시간 경과의 단서.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n집을 나서는 사람 다음에 버스에서 내리는 모습을 보여 이동 시간을 생략한다.\n\n0~2초: 인물이 집을 나서는 모습을 보여 준다\n2~6초: 이동 과정은 생략하고 목적지에 도착한 샷으로 컷한다\n6~8초: 의상과 소품을 유지해 같은 인물의 시간 경과를 알린다\n\n과정의 중간이 빠짐. 전후 변화가 이해됨. 시간 경과의 단서. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
