      "CAM-258": "비교 대상의 핵심: 화면이 짧게 번쩍이는 순간을 이용해 다음 장면으로 연결합니다.",
      "CAM-275": "비교 대상의 핵심: 현재 진행 중인 이야기에서 과거의 장면으로 이동합니다.",
      "CAM-240": "비교 대상의 핵심: 영상의 한 순간을 멈춰 사진처럼 유지합니다."
