    "shootingTips": "메모나 화면의 글자가 실제로 읽힐 길이를 확보하고 개인 정보는 사용하지 마세요.",
    "commonMistakes": "비교 대상의 핵심: 이야기를 이해하는 데 필요한 작은 물건이나 행동을 따로 보여 주는 샷입니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n추리 장면에 메모의 시각을 크게 넣어 관객에게 단서를 준다.\n\n촬영·표현의 핵심: 중요한 물건이나 세부 행동을 가까운 화면으로 삽입합니다.\n화면에서 반드시 확인할 조건: 중요한 물건의 삽입. 정보가 읽힐 시간. 본 장면과 연관.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n추리 장면에 메모의 시각을 크게 넣어 관객에게 단서를 준다.\n\n0~2초: 본 장면의 인물 행동을 보여 준다\n2~6초: 행동과 관련된 작은 물건을 가까이 삽입한다\n6~8초: 물건을 알아볼 시간 뒤 본 장면으로 돌아온다\n\n중요한 물건의 삽입. 정보가 읽힐 시간. 본 장면과 연관. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
