    "shootingTips": "흐린 구간이 너무 길면 내용을 놓치므로 필요한 순간만 사용하세요.",
    "commonMistakes": "비교 대상의 핵심: 초점을 일부러 맞추지 않아 대상의 윤곽을 흐리게 보여 줍니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n인물의 기억에서 현재로 돌아올 때 흐림을 이용해 시간 전환을 부드럽게 한다.\n\n촬영·표현의 핵심: 화면을 흐리게 했다가 다음 화면이 선명해지며 나타나도록 합니다.\n화면에서 반드시 확인할 조건: 선명함에서 흐림. 흐린 구간에 장면 교체. 다시 선명해짐.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n인물의 기억에서 현재로 돌아올 때 흐림을 이용해 시간 전환을 부드럽게 한다.\n\n0~2초: 첫 화면을 선명하게 보여 준다\n2~6초: 서서히 흐리게 하며 흐린 구간에서 두 번째 화면으로 바꾼다\n6~8초: 두 번째 장면이 선명해진다\n\n선명함에서 흐림. 흐린 구간에 장면 교체. 다시 선명해짐. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
