    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 걷는 배우 뒤로 새로운 거리가 나타나도록 선택 경계를 맞춰 장소를 바꾼다.\n\n0~2초: 전경 인물이나 물체의 윤곽이 분명하다\n2~6초: 그 윤곽을 따라 움직이는 선택 경계 뒤에 다른 장면을 드러낸다\n6~8초: 경계가 지나간 뒤 새 장면을 유지한다\n\n가림 영역의 이동. 윤곽과 경계. 다음 장면의 점진적 공개. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
