    "shootingTips": "빛 번짐이 핵심 얼굴을 오래 덮지 않게 강도와 시간을 줄이세요.",
    "commonMistakes": "비교 대상의 핵심: 카메라 안으로 빛이 새어 들어온 듯한 색 얼룩을 표현합니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n추억 사진 사이에 따뜻한 빛 얼룩을 넣어 오래된 기록 같은 분위기를 준다.\n\n촬영·표현의 핵심: 필름에 빛이 스며든 듯한 밝은 번짐을 사이에 넣어 장면을 바꿉니다.\n화면에서 반드시 확인할 조건: 밝은 색 번짐. 장면을 잠시 덮음. 다음 화면 공개.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n추억 사진 사이에 따뜻한 빛 얼룩을 넣어 오래된 기록 같은 분위기를 준다.\n\n0~2초: 첫 장면을 보여 준다\n2~6초: 따뜻한 빛 얼룩이 짧게 화면을 덮는 동안 다음 장면으로 바꾼다\n6~8초: 빛 번짐을 줄이고 새 장면을 선명하게 남긴다\n\n밝은 색 번짐. 장면을 잠시 덮음. 다음 화면 공개. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
