    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 컴퓨터를 보는 배우 뒤 화면 오류처럼 다른 장소로 넘어가 불안을 보탠다.\n\n0~2초: 안정된 디지털 화면으로 시작한다\n2~6초: 짧은 위치 어긋남과 색 분리를 넣으며 장면을 바꾼다\n6~8초: 오류를 끝내고 새 화면을 명료하게 보여 준다\n\n신호 오류 같은 변화. 짧은 위치나 색 어긋남. 장면 교체. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
