    "commonMistakes": "비교 대상의 핵심: 실제보다 느리게 재생해 빠른 동작의 세부를 보여 줍니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n허공의 물체를 둘러보는 합성으로 한 순간을 입체적으로 관찰하게 한다.\n\n촬영·표현의 핵심: 동작은 거의 멈춘 듯 보이는데 시점은 대상 주위를 이동하는 효과입니다.\n화면에서 반드시 확인할 조건: 동작이 거의 멈춘 상태. 주변 시점 이동. 여러 각도의 대상.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n허공의 물체를 둘러보는 합성으로 한 순간을 입체적으로 관찰하게 한다.\n\n0~2초: 동작의 정점에서 인물이 거의 멈춘 듯 보인다\n2~6초: 동작 진행은 매우 작게 유지하고 관찰 시점이 주변을 돌아간다\n6~8초: 다른 각도에서 같은 순간을 보여 준다\n\n동작이 거의 멈춘 상태. 주변 시점 이동. 여러 각도의 대상. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
