    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 배우가 방에 들어와 물건을 발견하고 나가는 사건을 한 흐름으로 전달한다.\n\n0~2초: 방에 들어오는 인물을 보여 준다\n2~6초: 물건 발견과 반응을 하나의 이어진 샷 안에서 보여 준다\n6~8초: 인물이 행동을 마무리하고 나가는 것으로 사건을 끝낸다\n\n하나의 사건 단위. 이어진 샷. 정보의 시작과 마무리. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
