    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 도마의 손과 음식을 작업자의 시점으로 보여 직접 요리하는 느낌을 준다.\n\n0~2초: 인물의 눈높이에서 앞 공간과 손을 본다\n2~6초: 주체의 시선 방향과 행동을 따라가며 바깥 인물 샷으로 바꾸지 않는다\n6~8초: 주체가 바라보는 대상에서 멈춘다\n\n인물 눈을 대신한 방향. 손이 전경에 올 수 있음. 외부 관찰과 차이. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
