    "shootingTips": "물의 저항과 시야 변화를 고려해 전문 수중 촬영팀과 안전을 확보하세요.",
    "commonMistakes": "비교 대상의 핵심: 물속에 카메라를 두어 물 아래의 모습을 보여 줍니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n전문 촬영팀이 수영자 옆을 따라가 연속되는 자세를 보여 준다.\n\n촬영·표현의 핵심: 물속에서 카메라가 이동하며 대상이나 공간을 따라갑니다.\n화면에서 반드시 확인할 조건: 카메라도 물속 이동. 대상과 간격 변화. 수중 배경의 연속.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n전문 촬영팀이 수영자 옆을 따라가 연속되는 자세를 보여 준다.\n\n0~2초: 물속 대상 옆에서 시작한다\n2~6초: 대상과 비슷한 속도로 수중 이동하며 간격을 유지한다\n6~8초: 대상 행동 끝에서 부드럽게 멈춘다\n\n카메라도 물속 이동. 대상과 간격 변화. 수중 배경의 연속. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
