    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n유리 벽 속 보행자를 따라가 도시의 겹친 모습을 보여 준다.\n\n촬영·표현의 핵심: 움직이는 대상의 반사된 모습을 따라 카메라가 이동합니다.\n화면에서 반드시 확인할 조건: 반사된 대상 추적. 각도에 따라 반사 변화. 실물과 겹침 이동.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n유리 벽 속 보행자를 따라가 도시의 겹친 모습을 보여 준다.\n\n0~2초: 반사면 안의 대상을 잡는다\n2~6초: 카메라가 반사된 대상을 따라가며 반사가 사라지지 않게 각도를 조절한다\n6~8초: 반사와 실제 공간 관계가 읽히게 끝낸다\n\n반사된 대상 추적. 각도에 따라 반사 변화. 실물과 겹침 이동. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
