    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n가로등 아래 걷는 사람의 그림자를 따라가 밤길의 시간을 느끼게 한다.\n\n촬영·표현의 핵심: 이동하는 그림자를 카메라가 따라가며 보여 줍니다.\n화면에서 반드시 확인할 조건: 이동하는 그림자. 카메라가 따라감. 빛에 따라 길이 변화.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n가로등 아래 걷는 사람의 그림자를 따라가 밤길의 시간을 느끼게 한다.\n\n0~2초: 이동하는 그림자의 시작을 보여 준다\n2~6초: 카메라는 그림자 경로를 따라가고 원래 인물은 보여 주지 않아도 된다\n6~8초: 그림자가 멈추는 면에서 끝낸다\n\n이동하는 그림자. 카메라가 따라감. 빛에 따라 길이 변화. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
