    "commonMistakes": "비교 대상의 핵심: 물체가 내보내는 열복사 정보를 전용 카메라로 시각화합니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n전용 야간 장비로 연출된 어두운 복도를 보여 제한된 시야의 긴장을 만든다.\n\n촬영·표현의 핵심: 빛을 증폭하거나 적외선을 활용하는 장비로 어두운 환경을 관찰합니다.\n화면에서 반드시 확인할 조건: 어두운 곳의 관찰. 증폭이나 적외선 문맥. 잡음과 제한된 색 가능.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n전용 야간 장비로 연출된 어두운 복도를 보여 제한된 시야의 긴장을 만든다.\n\n0~2초: 전용 야간 장비로 어두운 공간의 형태를 보여 준다\n2~6초: 인물의 작은 이동을 제한된 색과 잡음 속에서도 알아볼 수 있게 한다\n6~8초: 색 필터만 씌운 보통 저노출 영상으로 바꾸지 않는다\n\n어두운 곳의 관찰. 증폭이나 적외선 문맥. 잡음과 제한된 색 가능. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
