    "shootingTips": "착시를 만든 시점에서 벗어나면 관계가 깨집니다. 카메라를 먼저 고정하세요.",
    "commonMistakes": "동의어이거나 용례가 겹치는 명칭입니다. 카메라와 대상의 거리 차이를 이용해 크기나 위치 관계를 다르게 보이게 합니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 가까운 장난감 차와 먼 배우를 맞춰 차가 거대해 보이는 장난 장면을 만든다.\n\n촬영·표현의 핵심: 대상의 거리와 겹침을 맞춰 실제와 다른 크기 관계를 보여 줍니다.\n화면에서 반드시 확인할 조건: 거리로 맞춘 크기 착시. 겹치는 선의 정렬. 고정된 관찰 위치.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 가까운 장난감 차와 먼 배우를 맞춰 차가 거대해 보이는 장난 장면을 만든다.\n\n0~2초: 정렬된 거리 착시가 성립하는 고정 시점이다\n2~6초: 대상은 착시가 유지되는 작은 행동만 하고 카메라는 옆으로 돌지 않는다\n6~8초: 크기 관계 착시가 깨지지 않는 구도로 끝낸다\n\n거리로 맞춘 크기 착시. 겹치는 선의 정렬. 고정된 관찰 위치. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
