    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 같은 배우가 방 여러 위치에 동시에 있는 장면을 합성해 분신을 만든다.\n\n0~2초: 같은 배경에 합성할 인물들의 위치를 보여 준다\n2~6초: 동일 경로 촬영분의 여러 행동을 하나로 겹치되 배경은 어긋나지 않는다\n6~8초: 서로의 위치 관계가 읽히는 합성 화면을 유지한다\n\n동일 시점의 여러 촬영분. 합성되는 행동. 빛과 배경 일치. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
