    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n렌즈 축으로 복도 화면을 돌려 어지러운 감각을 표현한다.\n\n0~2초: 수평이 안정된 구도로 시작한다\n2~6초: 이번 예시는 렌즈 축을 기준으로 화면을 완만하게 회전하고 팬이나 오빗과 섞지 않는다\n6~8초: 회전을 끝낸 상태로 유지한다\n\n회전축의 선택. 화면 방향이나 보는 방향 변화. 축마다 다른 효과. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
