    "imagePromptExample": "가로 16:9. 고해상도 교육용 이미지, 지정한 미술 재료와 화풍을 일관되게 유지.\n\n둥근 형태의 공방 캐릭터가 도구를 설명하게 만들어 친근한 교육 화면을 만든다.\n\n촬영·표현의 핵심: 실제 모습보다 형태·색·비율을 의도적으로 바꾼 3D 애니메이션 표현입니다.\n화면에서 반드시 확인할 조건: 실제보다 과장된 형태. 선택된 재질과 색. 3D 공간의 입체감.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 지정 화풍의 애니메이션.\n\n둥근 형태의 공방 캐릭터가 도구를 설명하게 만들어 친근한 교육 화면을 만든다.\n\n0~2초: 3D 캐릭터와 미술 표현을 보여 준다\n2~6초: 과장된 비율과 재질을 유지하며 작은 인사 동작을 시킨다\n6~8초: 실사 인물로 바뀌지 않게 같은 디자인을 유지한다\n\n실제보다 과장된 형태. 선택된 재질과 색. 3D 공간의 입체감. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
