    "imagePromptExample": "가로 16:9. 고해상도 교육용 이미지, 지정한 미술 재료와 화풍을 일관되게 유지.\n\n종이 인형이 책상 위를 이동하게 해 수공예 애니메이션의 재미를 보여 준다.\n\n촬영·표현의 핵심: 한 장씩 움직임을 만든 듯 조금씩 끊어지는 리듬을 표현합니다.\n화면에서 반드시 확인할 조건: 조금씩 끊기는 동작. 물체의 손맛. 한 장씩 만든 리듬.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
