    "imagePromptExample": "가로 16:9. 고해상도 교육용 이미지, 지정한 미술 재료와 화풍을 일관되게 유지.\n\n춤 영상의 몸 동작을 따라 그려 자연스러운 동작과 그림의 질감을 결합한다.\n\n촬영·표현의 핵심: 실제로 찍은 동작을 참고하거나 따라 그려 애니메이션을 만듭니다.\n화면에서 반드시 확인할 조건: 실제 동작을 참고. 다시 그린 선과 색. 프레임별 움직임 연결.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 지정 화풍의 애니메이션.\n\n춤 영상의 몸 동작을 따라 그려 자연스러운 동작과 그림의 질감을 결합한다.\n\n0~2초: 참고 동작을 다시 그린 인물을 보여 준다\n2~6초: 실제 몸의 동작을 따르는 선과 색으로 짧은 걸음을 표현한다\n6~8초: 그림의 질감과 인물 형태를 유지한다\n\n실제 동작을 참고. 다시 그린 선과 색. 프레임별 움직임 연결. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
