    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 달리는 인물의 멈춤 순간을 느리게 해 결심을 강조한다.\n\n0~2초: 정상 속도의 동작을 보여 준다\n2~6초: 중요한 순간으로 가며 부드럽게 느려졌다 이후 다시 빨라진다\n6~8초: 정상 속도로 복귀한다\n\n장면 안 속도 변화. 부드러운 연결. 강조되는 순간. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
