    "shootingTips": "밝은 영역끼리 겹쳐 얼굴이 사라지지 않게 명암과 선택 영역을 조절하세요.",
    "commonMistakes": "비교 대상의 핵심: 같은 카메라 이동으로 찍은 여러 화면을 합쳐 하나의 장면을 만듭니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 인물 윤곽 안 숲을 겹쳐 자연을 떠올리는 생각을 시각화한다.\n\n촬영·표현의 핵심: 두 이미지나 장면이 한 화면에 겹쳐 보이도록 표현합니다.\n화면에서 반드시 확인할 조건: 두 이미지의 겹침. 서로의 명암 관계. 합성 영역.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 인물 윤곽 안 숲을 겹쳐 자연을 떠올리는 생각을 시각화한다.\n\n0~2초: 인물 윤곽을 보여 준다\n2~6초: 윤곽 안이나 위로 풍경 영상이 부드럽게 겹치며 두 이미지 관계를 유지한다\n6~8초: 두 대상이 동시에 읽히게 끝낸다\n\n두 이미지의 겹침. 서로의 명암 관계. 합성 영역. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
