    "commonMistakes": "비교 대상의 핵심: 초록색이나 파란색 같은 특정 배경색을 골라 지우고 다른 배경을 넣습니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 일반 거리 영상의 배우 뒤로 도형이 지나게 해 앞뒤 관계를 만든다.\n\n촬영·표현의 핵심: 움직이는 대상의 윤곽을 영상의 각 화면마다 따라 선택해 배경과 분리합니다.\n화면에서 반드시 확인할 조건: 프레임별 대상 윤곽. 머리카락 경계. 배경색에 의존하지 않음.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 일반 거리 영상의 배우 뒤로 도형이 지나게 해 앞뒤 관계를 만든다.\n\n0~2초: 배경색이 일정하지 않은 인물을 보여 준다\n2~6초: 움직임마다 대상의 윤곽을 따라 분리해 뒤로 다른 도형이 지나가게 한다\n6~8초: 대상의 경계가 갑자기 잘리거나 흔들리지 않게 한다\n\n프레임별 대상 윤곽. 머리카락 경계. 배경색에 의존하지 않음. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
