    "commonMistakes": "비교 대상의 핵심: 카메라 이동에 따라 가까운 것과 먼 것이 서로 다르게 움직여 보이게 합니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 인물 사진과 배경을 나눠 조금씩 움직여 정지 사진에 깊이를 더한다.\n\n촬영·표현의 핵심: 앞쪽과 뒤쪽 요소를 서로 다른 속도로 움직여 깊이감을 만듭니다.\n화면에서 반드시 확인할 조건: 앞뒤 요소의 속도 차이. 분리된 층. 이동 뒤 빈 부분 처리.\n\n같은 장면의 시작·중간·끝을 나란히 놓은 세 칸의 무자막 스토리보드로 표현한다. 각 칸의 인물과 소품은 동일하며 변화 단계가 구별되어야 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n장면의 성인 주인공은 30대 한국인으로, 단정한 검은 머리와 무늬 없는 차콜 계열 일상복을 착용한다. 인물 사진과 배경을 나눠 조금씩 움직여 정지 사진에 깊이를 더한다.\n\n0~2초: 전경과 배경을 나눈 사진을 보여 준다\n2~6초: 각 층을 다른 속도로 옆 이동해 시차를 만들고 빈 부분은 자연스럽게 채운다\n6~8초: 얼굴과 윤곽이 늘어나지 않은 새 시점으로 끝낸다\n\n앞뒤 요소의 속도 차이. 분리된 층. 이동 뒤 빈 부분 처리. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
