    "commonMistakes": "비교 대상의 핵심: 옛 브라운관 화면의 가로 주사선과 화면 곡률 같은 특징을 표현합니다.",
    "imagePromptExample": "가로 16:9. 고해상도 실사 기반 시네마틱 교육 이미지, 자연스러운 형태와 실제 공간의 원근감.\n\n가족 모임 영상에 옛 캠코더 같은 색과 줄무늬를 더해 추억을 전한다.\n\n촬영·표현의 핵심: 옛 비디오테이프처럼 색 번짐·줄무늬·화면 흔들림을 표현합니다.\n화면에서 반드시 확인할 조건: 비디오 색 번짐. 줄무늬와 흔들림. 필름 입자와 구분.\n\n한 장의 완성된 화면으로 표현한다. 장면에 명시된 빛과 배치를 유지하고 핵심 대상의 형태가 읽히게 한다.\n핵심 조건을 다른 샷 크기·시점·움직임·화풍으로 바꾸지 않는다. 불필요한 글자, 자막, 워터마크, 로고, 촬영 장비와 지시하지 않은 군중을 추가하지 않는다.",
    "videoPromptExample": "가로 16:9, 8초 길이의 고품질 시네마틱 교육 영상.\n\n가족 모임 영상에 옛 캠코더 같은 색과 줄무늬를 더해 추억을 전한다.\n\n0~2초: 가족 기록 같은 연속 행동을 보여 준다\n2~6초: 옛 비디오의 약한 색 번짐과 수평 잡음을 더하되 큰 점멸은 피한다\n6~8초: 원래 동작이 식별되는 상태로 마친다\n\n비디오 색 번짐. 줄무늬와 흔들림. 필름 입자와 구분. 주인공의 외형·의상과 장소·소품의 연속성을 유지한다. 명시한 변화 외에 임의의 줌·회전·카메라 흔들림·추가 컷을 넣지 않는다. 텍스트, 자막, 로고, 워터마크, 촬영 장비는 보이지 않는다.",
